.node{padding:2px;position:absolute;display:flex;justify-content:space-between;flex-direction:row}.node:focus-within{border:.5px solid;border-color:#5e72e4}.node-name{margin-top:calc(.05rem + 4px);font-size:80%;text-align:center}.output-pins{text-align:-webkit-right}.node-selected{border:.5px solid;border-color:#5e72e4}.node-flow-group{border:2px solid #7c3aed;border-radius:8px;background:linear-gradient(135deg, #f3f4f6 0%, #e5e7eb 100%)}.node-flow-group .node-name{color:#7c3aed;font-weight:600}.node-flow-group::before{content:"🔗";position:absolute;top:-8px;left:-8px;background:#7c3aed;color:#fff;border-radius:50%;width:20px;height:20px;display:flex;align-items:center;justify-content:center;font-size:10px;z-index:1}.node-flow-proxy{border:2px solid #059669;border-radius:8px;background:linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%)}.node-flow-proxy .node-name{color:#059669;font-weight:600}.node-flow-proxy::before{content:"📦";position:absolute;top:-8px;left:-8px;background:#059669;color:#fff;border-radius:50%;width:20px;height:20px;display:flex;align-items:center;justify-content:center;font-size:10px;z-index:1}.node-flow-proxy:hover{transform:translateY(-2px);box-shadow:0 4px 12px rgba(5,150,105,.3);transition:all .2s ease}